CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(50) PRIMARY KEY, applied_at DATETIME(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE households (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'PKR', timezone VARCHAR(80) NOT NULL DEFAULT 'Asia/Karachi', created_at DATETIME(6) NOT NULL, UNIQUE(id,uuid)) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at DATETIME(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE household_memberships (household_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, role VARCHAR(30) NOT NULL, active TINYINT NOT NULL DEFAULT 1, PRIMARY KEY(household_id,user_id), FOREIGN KEY(household_id) REFERENCES households(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE members (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, relationship VARCHAR(80) NOT NULL, created_at DATETIME(6) NOT NULL, UNIQUE(household_id,id), FOREIGN KEY(household_id) REFERENCES households(id)) ENGINE=InnoDB;
CREATE TABLE ledger_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, class VARCHAR(20) NOT NULL, system_key VARCHAR(80) NULL, UNIQUE(household_id,id), UNIQUE(household_id,system_key), FOREIGN KEY(household_id) REFERENCES households(id)) ENGINE=InnoDB;
CREATE TABLE accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, ledger_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, type VARCHAR(30) NOT NULL, currency CHAR(3) NOT NULL, active TINYINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, UNIQUE(household_id,id), UNIQUE(ledger_id), FOREIGN KEY(household_id,ledger_id) REFERENCES ledger_accounts(household_id,id)) ENGINE=InnoDB;
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, ledger_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, type VARCHAR(20) NOT NULL, icon VARCHAR(20) NOT NULL DEFAULT 'circle', UNIQUE(household_id,id), FOREIGN KEY(household_id,ledger_id) REFERENCES ledger_accounts(household_id,id)) ENGINE=InnoDB;
CREATE TABLE transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, type VARCHAR(30) NOT NULL, effective_date DATE NOT NULL, description VARCHAR(500) NOT NULL, amount DECIMAL(20,6) NOT NULL, status VARCHAR(30) NOT NULL, source_key VARCHAR(190) NOT NULL, payload_hash CHAR(64) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at DATETIME(6) NOT NULL, reversal_of BIGINT UNSIGNED NULL, row_version INT NOT NULL DEFAULT 1, UNIQUE(household_id,id), UNIQUE(household_id,source_key), INDEX(household_id,effective_date), FOREIGN KEY(household_id) REFERENCES households(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE transaction_splits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, household_id BIGINT UNSIGNED NOT NULL, transaction_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NULL, member_id BIGINT UNSIGNED NULL, project VARCHAR(120) NULL, tags VARCHAR(250) NULL, amount DECIMAL(20,6) NOT NULL, FOREIGN KEY(household_id,transaction_id) REFERENCES transactions(household_id,id), FOREIGN KEY(household_id,category_id) REFERENCES categories(household_id,id), FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,id)) ENGINE=InnoDB;
CREATE TABLE journal_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, transaction_id BIGINT UNSIGNED NOT NULL UNIQUE, effective_date DATE NOT NULL, created_at DATETIME(6) NOT NULL, UNIQUE(household_id,id), FOREIGN KEY(household_id,transaction_id) REFERENCES transactions(household_id,id)) ENGINE=InnoDB;
CREATE TABLE journal_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, household_id BIGINT UNSIGNED NOT NULL, journal_id BIGINT UNSIGNED NOT NULL, ledger_id BIGINT UNSIGNED NOT NULL, debit DECIMAL(20,6) NOT NULL DEFAULT 0, credit DECIMAL(20,6) NOT NULL DEFAULT 0, category_id BIGINT UNSIGNED NULL, member_id BIGINT UNSIGNED NULL, project VARCHAR(120) NULL, FOREIGN KEY(household_id,journal_id) REFERENCES journal_entries(household_id,id), FOREIGN KEY(household_id,ledger_id) REFERENCES ledger_accounts(household_id,id), FOREIGN KEY(household_id,category_id) REFERENCES categories(household_id,id), FOREIGN KEY(household_id,member_id) REFERENCES members(household_id,id), CHECK (debit >= 0 AND credit >= 0 AND ((debit > 0 AND credit = 0) OR (credit > 0 AND debit = 0))), INDEX(household_id,ledger_id)) ENGINE=InnoDB;
CREATE TABLE bills (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, amount DECIMAL(20,6) NOT NULL, due_date DATE NOT NULL, category_id BIGINT UNSIGNED NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'open', created_at DATETIME(6) NOT NULL, UNIQUE(household_id,id), FOREIGN KEY(household_id,category_id) REFERENCES categories(household_id,id)) ENGINE=InnoDB;
CREATE TABLE bill_allocations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, household_id BIGINT UNSIGNED NOT NULL, bill_id BIGINT UNSIGNED NOT NULL, transaction_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(20,6) NOT NULL, UNIQUE(bill_id,transaction_id), FOREIGN KEY(household_id,bill_id) REFERENCES bills(household_id,id), FOREIGN KEY(household_id,transaction_id) REFERENCES transactions(household_id,id)) ENGINE=InnoDB;
CREATE TABLE budgets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NOT NULL, month CHAR(7) NOT NULL, amount DECIMAL(20,6) NOT NULL, UNIQUE(household_id,category_id,month), FOREIGN KEY(household_id,category_id) REFERENCES categories(household_id,id)) ENGINE=InnoDB;
CREATE TABLE funds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, purpose VARCHAR(30) NOT NULL, target DECIMAL(20,6) NOT NULL, target_date DATE NULL, account_id BIGINT UNSIGNED NOT NULL, created_at DATETIME(6) NOT NULL, UNIQUE(household_id,id), FOREIGN KEY(household_id,account_id) REFERENCES accounts(household_id,id)) ENGINE=InnoDB;
CREATE TABLE fund_allocations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, household_id BIGINT UNSIGNED NOT NULL, fund_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(20,6) NOT NULL, source_key VARCHAR(190) NOT NULL, created_at DATETIME(6) NOT NULL, UNIQUE(household_id,source_key), FOREIGN KEY(household_id,fund_id) REFERENCES funds(household_id,id)) ENGINE=InnoDB;
CREATE TABLE obligations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, direction VARCHAR(20) NOT NULL, ledger_id BIGINT UNSIGNED NOT NULL, original_amount DECIMAL(20,6) NOT NULL, due_date DATE NULL, created_at DATETIME(6) NOT NULL, UNIQUE(household_id,id), FOREIGN KEY(household_id,ledger_id) REFERENCES ledger_accounts(household_id,id)) ENGINE=InnoDB;
CREATE TABLE recurring_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, amount DECIMAL(20,6) NOT NULL, category_id BIGINT UNSIGNED NOT NULL, frequency VARCHAR(20) NOT NULL, next_date DATE NOT NULL, anchor_day INT NOT NULL, active TINYINT NOT NULL DEFAULT 1, UNIQUE(household_id,id), FOREIGN KEY(household_id,category_id) REFERENCES categories(household_id,id)) ENGINE=InnoDB;
CREATE TABLE recurring_occurrences (rule_id BIGINT UNSIGNED NOT NULL, occurrence_date DATE NOT NULL, bill_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(rule_id,occurrence_date), FOREIGN KEY(rule_id) REFERENCES recurring_rules(id), FOREIGN KEY(bill_id) REFERENCES bills(id)) ENGINE=InnoDB;
CREATE TABLE periods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, household_id BIGINT UNSIGNED NOT NULL, month CHAR(7) NOT NULL, locked TINYINT NOT NULL DEFAULT 0, reason VARCHAR(250) NULL, UNIQUE(household_id,month), FOREIGN KEY(household_id) REFERENCES households(id)) ENGINE=InnoDB;
CREATE TABLE documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, transaction_id BIGINT UNSIGNED NULL, filename VARCHAR(190) NOT NULL, storage_key VARCHAR(100) NOT NULL, mime VARCHAR(100) NOT NULL, bytes BIGINT NOT NULL, checksum CHAR(64) NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(household_id) REFERENCES households(id), FOREIGN KEY(household_id,transaction_id) REFERENCES transactions(household_id,id)) ENGINE=InnoDB;
CREATE TABLE audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, entity_uuid CHAR(36) NULL, details JSON NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(household_id) REFERENCES households(id)) ENGINE=InnoDB;
CREATE TABLE outbox_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, uuid CHAR(36) NOT NULL UNIQUE, household_id BIGINT UNSIGNED NOT NULL, event_type VARCHAR(80) NOT NULL, entity_uuid CHAR(36) NOT NULL, created_at DATETIME(6) NOT NULL, dispatched_at DATETIME(6) NULL, FOREIGN KEY(household_id) REFERENCES households(id)) ENGINE=InnoDB;
CREATE TABLE login_attempts (key_hash CHAR(64) PRIMARY KEY, attempts INT NOT NULL DEFAULT 0, last_at DATETIME(6) NOT NULL) ENGINE=InnoDB;
INSERT INTO schema_migrations VALUES ('001_core', UTC_TIMESTAMP(6));
